/**
 * HOW THIS SCRIPT WORKS
 * ---------------------
 * Comments are NOT generated by calling an API at runtime.
 * They are written by Claude Code as part of the daily workflow.
 *
 * Workflow each day:
 *   1. node scripts/fetch-tweets.js      → pulls today's tweets into data/tweets.json
 *   2. Claude Code reads data/tweets.json, then for every tweet that has images,
 *      downloads them to /tmp/tweet-images/ and reads them visually before writing.
 *   3. Claude Code writes the COMMENTS map below with fresh tweet IDs + comments
 *      in Ananda's voice, following .claude/skills/comment-voice.md
 *   4. node scripts/write-comments.js    → stamps comments onto data/tweets.json
 *   5. node scripts/generate-dashboard.js → rebuilds the dashboard HTML
 *
 * To regenerate: tell Claude Code "write comments".
 * Never hardcode IDs from a previous session — tweet IDs change every day.
 */

import { readFileSync, writeFileSync } from 'fs';

const TWEETS_FILE = 'data/tweets.json';

